/*
 * ======================================================================================
 * PROJECT: SMART WASTE-TO-RESOURCE SYSTEM (NCSC 2026)
 * FIRMWARE: ESP32 Multi-Sensor Acquisition & Autonomous Servo Routing System
 * VERSION: v2.4 (Production / Science Exhibition Release)
 * AUTHOR: NCSC Project Team
 * HARDWARE: ESP32-WROOM-32, HX711 Load Cell, Inductive LJ12A3-4-Z/BX, Servo MG996R, OLED SSD1306
 * ======================================================================================
 */

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <ESP32Servo.h>
#include <HX711.h>

// PIN DEFINITIONS
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
#define SCREEN_ADDRESS 0x3C

#define PIN_SERVO_FLAP       18
#define PIN_HX711_DOUT       19
#define PIN_HX711_SCK        23
#define PIN_MOISTURE_ANALOG  34
#define PIN_INDUCTIVE_METAL  35
#define PIN_STATUS_LED_WET   25
#define PIN_STATUS_LED_PLAST 26
#define PIN_STATUS_LED_OTHER 27
#define PIN_BUZZER           14

// SERVO ROUTING CALIBRATION ANGLES
const int ANGLE_REST_READY = 90;
const int ANGLE_WET_WASTE  = 135;
const int ANGLE_PLASTIC    = 105;
const int ANGLE_OTHER      = 70;
const int ANGLE_REJECT     = 45;

// THRESHOLDS
const int MOISTURE_THRESHOLD_WET = 2200; // 12-bit ADC threshold (0-4095)
const float MIN_DETECTABLE_MASS  = 5.0;   // Grams

// OBJECT INSTANCES
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);
Servo routingServo;
HX711 scale;

// GLOBAL STATE
float currentMass = 0.0;
bool metalDetected = false;
int moistureRaw = 0;
String currentClassification = "READY";
int confidenceLevel = 0;

void setup() {
  Serial.begin(115200);
  delay(500);
  Serial.println(F("[SYSTEM INIT] NCSC Smart Waste Controller Initializing..."));

  // Pins Setup
  pinMode(PIN_INDUCTIVE_METAL, INPUT_PULLUP);
  pinMode(PIN_MOISTURE_ANALOG, INPUT);
  pinMode(PIN_STATUS_LED_WET, OUTPUT);
  pinMode(PIN_STATUS_LED_PLAST, OUTPUT);
  pinMode(PIN_STATUS_LED_OTHER, OUTPUT);
  pinMode(PIN_BUZZER, OUTPUT);

  // Servo Configuration
  ESP32PWM::allocateTimer(0);
  routingServo.setPeriodHertz(50);
  routingServo.attach(PIN_SERVO_FLAP, 500, 2400);
  routingServo.write(ANGLE_REST_READY);

  // Scale (HX711) Setup
  scale.begin(PIN_HX711_DOUT, PIN_HX711_SCK);
  scale.set_scale(420.09f); // Calibration factor
  scale.tare();

  // OLED Setup
  if (!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
    Serial.println(F("[ERROR] OLED SSD1306 allocation failed"));
  } else {
    display.clearDisplay();
    display.setTextSize(1);
    display.setTextColor(SSD1306_WHITE);
    display.setCursor(0, 0);
    display.println(F("NCSC SMART BIN v2.4"));
    display.println(F("Status: ONLINE"));
    display.println(F("Sensors: CALIBRATED"));
    display.display();
  }

  beepSuccess();
  Serial.println(F("[SYSTEM READY] Waiting for waste insertion..."));
}

void loop() {
  // 1. Read Tare / Mass
  if (scale.is_ready()) {
    currentMass = scale.get_units(3);
    if (currentMass < 0) currentMass = 0;
  }

  // 2. Read Physical Sensors
  moistureRaw = analogRead(PIN_MOISTURE_ANALOG);
  metalDetected = (digitalRead(PIN_INDUCTIVE_METAL) == LOW); // Active Low sensor

  // 3. Process AI Serial Packet if available from Camera Module
  if (Serial.available()) {
    String incoming = Serial.readStringUntil('\n');
    incoming.trim();
    if (incoming.startsWith("CLASSIFY:")) {
      parseAICommand(incoming);
    }
  }

  // 4. Update OLED Display
  updateDisplay();
  delay(150);
}

void parseAICommand(String cmd) {
  // Example command: CLASSIFY:PLASTIC,CONF:96
  int cIdx = cmd.indexOf(':');
  int commaIdx = cmd.indexOf(',');
  String category = cmd.substring(cIdx + 1, commaIdx);
  int confIdx = cmd.indexOf("CONF:");
  int conf = cmd.substring(confIdx + 5).toInt();

  currentClassification = category;
  confidenceLevel = conf;

  executeSortingRouting(category, conf);
}

void executeSortingRouting(String cat, int conf) {
  Serial.print(F("[ACTION] Routing waste stream: "));
  Serial.print(cat);
  Serial.print(F(" | Conf: "));
  Serial.println(conf);

  int targetAngle = ANGLE_REST_READY;

  if (conf < 65) {
    targetAngle = ANGLE_REJECT;
    digitalWrite(PIN_STATUS_LED_OTHER, HIGH);
  } else if (metalDetected || cat == "METAL" || cat == "PAPER" || cat == "GLASS" || cat == "OTHER") {
    targetAngle = ANGLE_OTHER;
    digitalWrite(PIN_STATUS_LED_OTHER, HIGH);
  } else if (cat == "WET" || moistureRaw > MOISTURE_THRESHOLD_WET) {
    targetAngle = ANGLE_WET_WASTE;
    digitalWrite(PIN_STATUS_LED_WET, HIGH);
  } else if (cat == "PLASTIC") {
    targetAngle = ANGLE_PLASTIC;
    digitalWrite(PIN_STATUS_LED_PLAST, HIGH);
  } else {
    targetAngle = ANGLE_REJECT;
  }

  // Animate Servo Flap
  routingServo.write(targetAngle);
  beepChime();
  delay(1800); // Allow item to drop through chute into recovery container

  // Return to Neutral Position
  routingServo.write(ANGLE_REST_READY);
  digitalWrite(PIN_STATUS_LED_WET, LOW);
  digitalWrite(PIN_STATUS_LED_PLAST, LOW);
  digitalWrite(PIN_STATUS_LED_OTHER, LOW);
  currentClassification = "READY";
}

void updateDisplay() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print(F("SMART RECOVERY VAULT"));
  display.drawLine(0, 9, 128, 9, SSD1306_WHITE);

  display.setCursor(0, 14);
  display.print(F("Mass: "));
  display.print(currentMass, 1);
  display.print(F(" g"));

  display.setCursor(0, 26);
  display.print(F("Moist: "));
  display.print(moistureRaw > MOISTURE_THRESHOLD_WET ? F("HIGH [WET]") : F("LOW [DRY]"));

  display.setCursor(0, 38);
  display.print(F("Metal: "));
  display.print(metalDetected ? F("DETECTED") : F("NONE"));

  display.setCursor(0, 50);
  display.print(F("Stream: "));
  display.print(currentClassification);
  display.display();
}

void beepSuccess() {
  tone(PIN_BUZZER, 1800, 150);
  delay(180);
  tone(PIN_BUZZER, 2400, 200);
}

void beepChime() {
  tone(PIN_BUZZER, 1400, 100);
}
